contracts/SCI.sol.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity 0.8.28;

import {IVerifier} from './Verifiers/IVerifier.sol';
import {ISciRegistry} from './SciRegistry/ISciRegistry.sol';
import {Initializable} from '@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol';
import {Ownable2StepUpgradeable} from '@openzeppelin/contracts-upgradeable/access/Ownable2StepUpgradeable.sol';

/**
 * @title SCI
 * @dev This contract facilitates interaction with the SCI protocol, offering a simplified interface
 * for apps and wallets. Apps and wallets can also directly interact with the
 * Registry and verifiers directly if desired, bypassing this contract.
 * @custom:security-contact security@sci.domains
 */
contract SCI is Initializable, Ownable2StepUpgradeable {
    ISciRegistry public registry;

    /**
     *  @dev Emitted when the Registry is changed.
     */
    event RegistrySet(address indexed oldRegistryAddress, address indexed newRegistryAddress);

    /**
     * @dev Initializes the SCI contract with the owner and registry address.
     * Can only be called once during contract deployment.
     *
     * @param owner The owner of this contract.
     * @param _registry The address of the registry to be used by the contract.
     */
    function initialize(address owner, address _registry) external initializer {
        __Ownable2Step_init();
        __Ownable_init(owner);
        setRegistry(_registry);
    }

    /**
     * @dev Returns info from the domain.
     *
     * @param domainHash The namehash of the domain.
     */
    function domainHashToRecord(
        bytes32 domainHash
    )
        external
        view
        returns (
            address owner,
            IVerifier verifier,
            uint256 lastOwnerSetTime,
            uint256 lastVerifierSetTime
        )
    {
        return registry.domainHashToRecord(domainHash);
    }

    /**
     * @dev Same as isVerifiedForDomainHash but for multiple domains.
     *
     * @param domainHashes An array of domain hashes.
     * @param contractAddress The address of the contract is being verified.
     * @param chainId The id of the chain the contract is deployed in.
     * @return an array of uint256 representing the time when the contract was verified for each domain
     * or 0 if it wasn't.
     *
     * Note: If there is no verifier set then it returns false for that `domainHash`.
     */
    function isVerifiedForMultipleDomainHashes(
        bytes32[] memory domainHashes,
        address contractAddress,
        uint256 chainId
    ) external view returns (uint256[] memory) {
        uint256[] memory domainsVerification = new uint256[](domainHashes.length);
        uint256 domainHashesLength = domainHashes.length;
        for (uint256 i; i < domainHashesLength; ) {
            domainsVerification[i] = isVerifiedForDomainHash(
                domainHashes[i],
                contractAddress,
                chainId
            );
            unchecked {
                ++i;
            }
        }
        return domainsVerification;
    }

    /**
     * @dev Returns if the `contractAddress` deployed in the chain with id `chainId` is verified.
     * to interact with the domain with namehash `domainHash`.
     * @param domainHash The namehash of the domain the contract is interacting with
     * @param contractAddress The address of the contract is being verified.
     * @param chainId The id of the chain the contract is deployed in.
     * @return a uint256 representing the time when the contract was verified.
     * If the contract is not verified, it returns 0.
     *
     * Note: If there is no verifier set then it returns 0.
     */
    function isVerifiedForDomainHash(
        bytes32 domainHash,
        address contractAddress,
        uint256 chainId
    ) public view returns (uint256) {
        (, IVerifier verifier, , ) = registry.domainHashToRecord(domainHash);

        if (address(verifier) == address(0)) {
            return 0;
        }

        return verifier.isVerified(domainHash, contractAddress, chainId);
    }

    /**
     * @dev Sets a new registry.
     *
     * @param newRegistry The address of the new SCI Registry.
     *
     * May emit a {RegistrySet} event.
     */
    function setRegistry(address newRegistry) public onlyOwner {
        address oldRegistryAddress = address(registry);
        registry = ISciRegistry(newRegistry);
        emit RegistrySet(oldRegistryAddress, newRegistry);
    }
}

contracts/SciRegistry/SciRegistry.sol.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity 0.8.28;

import {Pausable} from '@openzeppelin/contracts/utils/Pausable.sol';
import {AccessControlDefaultAdminRules} from '@openzeppelin/contracts/access/extensions/AccessControlDefaultAdminRules.sol';
import {IVerifier} from '../Verifiers/IVerifier.sol';
import {ISciRegistry} from './ISciRegistry.sol';
import {DomainManager} from '../DomainMangager/DomainManager.sol';

/**
 * @title Registry
 * @dev See {ISciRegistry}.
 * @custom:security-contact security@sci.domains
 */
contract SciRegistry is ISciRegistry, AccessControlDefaultAdminRules, DomainManager, Pausable {
    /**
     * @dev Structure to hold domain record details, including:
     * - owner: Address of the domain owner.
     * - verifier: Address of the verifier contract associated with the domain.
     * - ownerSetTime: Timestamp of when the domain owner was last set.
     * - verifierSetTime: Timestamp of when the verifier was last set.
     */
    struct Record {
        address owner;
        IVerifier verifier;
        uint256 ownerSetTime;
        uint256 verifierSetTime;
    }

    // Role that allows managing registrar roles.
    bytes32 public constant REGISTRAR_MANAGER_ROLE = keccak256('REGISTRAR_MANAGER_ROLE');
    // Role that allows registering domains.
    bytes32 public constant REGISTRAR_ROLE = keccak256('REGISTRAR_ROLE');
    // Role that allows to pause the contract.
    bytes32 public constant PAUSER_ROLE = keccak256('PAUSER_ROLE');

    /**
     * @dev Maps the namehash of a domain to a Record.
     */
    mapping(bytes32 nameHash => Record domain) public domainHashToRecord;

    /**
     * @dev Constructor to initialize the Registry contract.
     * Sets the REGISTRAR_MANAGER_ROLE as the admin role of REGISTRAR_ROLE.
     * @param _initialDelay The {defaultAdminDelay}. See AccessControlDefaultAdminRules for more information.
     * @param _initialDefaultAdmin The {initialDefaultAdmin}. See AccessControlDefaultAdminRules for more information.
     */
    constructor(
        uint48 _initialDelay,
        address _initialDefaultAdmin
    )
        AccessControlDefaultAdminRules(_initialDelay, _initialDefaultAdmin)
        DomainManager(address(this))
    {
        _setRoleAdmin(REGISTRAR_ROLE, REGISTRAR_MANAGER_ROLE);
    }

    /**
     * @dev See {ISciRegistry-registerDomain}.
     */
    function registerDomain(address owner, bytes32 domainHash) external {
        _registerDomain(owner, domainHash);
    }

    /**
     * @dev See {ISciRegistry-registerDomainWithVerifier}.
     */
    function registerDomainWithVerifier(
        address owner,
        bytes32 domainHash,
        IVerifier verifier
    ) external {
        _registerDomain(owner, domainHash);
        _setVerifier(domainHash, verifier);
    }

    /**
     * @dev Pauses registering a domain and setting a verifier.
     */
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @dev Unpauses registering a domain and setting a verifier.
     */
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    /**
     * @dev See {ISciRegistry-isDomainOwner}.
     */
    function isDomainOwner(
        bytes32 domainHash,
        address account
    ) external view virtual override returns (bool) {
        return domainOwner(domainHash) == account;
    }

    /**
     * @dev See {ISciRegistry-setVerifier}.
     */
    function setVerifier(
        bytes32 domainHash,
        IVerifier verifier
    ) external onlyDomainOwner(msg.sender, domainHash) {
        _setVerifier(domainHash, verifier);
    }

    /**
     * @dev See {ISciRegistry-domainVerifier}.
     */
    function domainVerifier(bytes32 domainHash) external view virtual returns (IVerifier) {
        return domainHashToRecord[domainHash].verifier;
    }

    /**
     * @dev See {ISciRegistry-domainVerifierSetTime}.
     */
    function domainVerifierSetTime(bytes32 domainHash) external view virtual returns (uint256) {
        return domainHashToRecord[domainHash].verifierSetTime;
    }

    /**
     * @dev Grants a role to an account.
     * @param role The role to grant.
     * @param account The account receiving the role.
     *
     * Note: Overrides the OpenZeppelin function to require the
     * caller to have the admin role for the role being granted.
     */
    function grantRole(bytes32 role, address account) public override onlyRole(getRoleAdmin(role)) {
        _grantRole(role, account);
    }

    /**
     * @dev See {ISciRegistry-domainOwner}.
     */
    function domainOwner(bytes32 domainHash) public view virtual override returns (address) {
        return domainHashToRecord[domainHash].owner;
    }

    /**
     * @dev Base function to register a domain.
     *
     * @param owner The owner of the domain.
     * @param domainHash The namehash of the domain being registered.
     *
     * Requirements:
     *
     * - the owner must be authorized by the authorizer.
     * - The contract must not be paused.
     *
     * May emit a {DomainRegistered} event.
     */
    function _registerDomain(
        address owner,
        bytes32 domainHash
    ) private onlyRole(REGISTRAR_ROLE) whenNotPaused {
        _setDomainOwner(domainHash, owner);
        emit DomainRegistered(msg.sender, owner, domainHash);
    }

    /**
     * @dev Sets the verifier, updates the verifier timestamp and
     * emits VerifierSet events.
     * All updates to a verifier should be through this function.
     *
     * Requirements:
     *
     * - The contract must not be paused.
     */
    function _setVerifier(bytes32 domainHash, IVerifier verifier) private whenNotPaused {
        IVerifier oldVerifier = domainHashToRecord[domainHash].verifier;
        domainHashToRecord[domainHash].verifier = verifier;
        domainHashToRecord[domainHash].verifierSetTime = block.timestamp;
        emit VerifierSet(msg.sender, domainHash, oldVerifier, verifier);
    }

    /**
     * @dev Sets the owner of a domain,
     * All updates to an owner should be through this function.
     */
    function _setDomainOwner(bytes32 domainHash, address owner) private {
        address oldOwner = domainHashToRecord[domainHash].owner;
        domainHashToRecord[domainHash].owner = owner;
        domainHashToRecord[domainHash].ownerSetTime = block.timestamp;
        emit OwnerSet(msg.sender, domainHash, oldOwner, owner);
    }
}

contracts/Verifiers/IVerifier.sol.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity 0.8.28;

/**
 * @title IVerifier
 * @dev Required interface of a Verifier compliant contract for the SCI Registry.
 * @custom:security-contact security@sci.domains
 */
interface IVerifier {
    /**
     * @dev Verifies if a contract in a specific chain is authorized
     * to interact within a domain.
     * @param domainHash The domain's namehash.
     * @param contractAddress The address of the contract trying to be verified.
     * @param chainId The chain where the contract is deployed.
     * @return a uint256 representing the time when the contract was verified.
     * If the contract is not verified, it returns 0.
     *
     * Note: The return timestamp is a best effor approach to provide the time when the contract
     * was verified. For verifiers that can't know when the contract was verified they could
     * return when the verifier was deployed.
     */
    function isVerified(
        bytes32 domainHash,
        address contractAddress,
        uint256 chainId
    ) external view returns (uint256);
}

contracts/Verifiers/PublicListVerifier.s.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity 0.8.28;

import {IVerifier} from './IVerifier.sol';
import {DomainManager} from '../DomainMangager/DomainManager.sol';

/**
 * @title PublicListVerifier
 * @dev This contract implements the Verifier interface.
 * Domain owners can add or remove addresses that can interact within their domain.
 *
 * If the owner of the domain sets a contract address with MAX_INT as chain id then it assumes
 * this contract is verified for all chains for that domain.
 * @custom:security-contact security@sci.domains
 */
contract PublicListVerifier is IVerifier, DomainManager {
    uint256 private constant MAX_INT = 2 ** 256 - 1;

    // Domain hash -> contract address -> chain id -> true/false.
    mapping(bytes32 domainHash => mapping(address contractAddress => mapping(uint256 chainId => uint256 registerTimestamp)))
        public verifiedContracts;

    /**
     *  @dev Emitted when the `msgSender` removes an address to a `domainHash` for a `chainId`.
     */
    event AddressRemoved(
        bytes32 indexed domainHash,
        uint256 indexed chainId,
        address indexed contractAddress,
        address msgSender
    );

    /**
     *  @dev Emitted when the `msgSender` adds an address to a `domainHash` for a `chainId`.
     */
    event AddressAdded(
        bytes32 indexed domainHash,
        uint256 indexed chainId,
        address indexed contractAddress,
        address msgSender
    );

    constructor(address _registry) DomainManager(_registry) {}

    /**
     * @dev Adds multiple addresses in multiple chains to the domain.
     *
     * Requirements:
     *
     * - The caller must be the owner of the domain.
     */
    function addAddresses(
        bytes32 domainHash,
        address[] calldata contractAddresses,
        uint256[][] calldata chainIds
    ) external onlyDomainOwner(msg.sender, domainHash) {
        for (uint256 i; i < contractAddresses.length; ) {
            for (uint256 j; j < chainIds[i].length; ) {
                verifiedContracts[domainHash][contractAddresses[i]][chainIds[i][j]] = block
                    .timestamp;
                emit AddressAdded(domainHash, chainIds[i][j], contractAddresses[i], msg.sender);
                unchecked {
                    ++j;
                }
            }
            unchecked {
                ++i;
            }
        }
    }

    /**
     * @dev Removes multiple addresses in multiple chains to the domain.
     *
     * Requirements:
     *
     * - The caller must be the owner of the domain.
     */
    function removeAddresses(
        bytes32 domainHash,
        address[] calldata contractAddresses,
        uint256[][] calldata chainIds
    ) external onlyDomainOwner(msg.sender, domainHash) {
        for (uint256 i; i < contractAddresses.length; ) {
            for (uint256 j; j < chainIds[i].length; ++j) {
                verifiedContracts[domainHash][contractAddresses[i]][chainIds[i][j]] = 0;
                emit AddressRemoved(domainHash, chainIds[i][j], contractAddresses[i], msg.sender);
                unchecked {
                    ++j;
                }
            }
            unchecked {
                ++i;
            }
        }
    }

    /**
     * @dev See {IVerifier-isVerified}.
     */
    function isVerified(
        bytes32 domainHash,
        address contractAddress,
        uint256 chainId
    ) external view returns (uint256) {
        uint256 verifiedContract = verifiedContracts[domainHash][contractAddress][chainId];

        if (verifiedContract != 0) {
            return verifiedContract;
        }

        verifiedContract = verifiedContracts[domainHash][contractAddress][MAX_INT];
        if (verifiedContract != 0) {
            return verifiedContract;
        }

        // Return 0 if no match is found
        return 0;
    }
}

